"""Explicit reviewed documents/art only; never exports the repository or runtime files."""
from pathlib import Path
import argparse, hashlib, html, json, shutil
from markdown_it import MarkdownIt
root=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('--target',required=True);p.add_argument('--owner-origin',required=True);args=p.parse_args()
out=Path(args.target).resolve()/'site/reviews/miao-beat';out.mkdir(parents=True,exist_ok=True)
md=MarkdownIt('commonmark',{'html':False}).enable('table')
entries=[('plan','计划与确认边界','docs/plan.md'),('product','作品、出路与键位','docs/research/product-and-keyboard.md'),('audio','声音与节拍','docs/research/audio-and-timing.md'),('animation','角色与动画','docs/research/animation-and-experience.md'),('recording','参考谱与小文件','docs/research/scores.md'),('samples','真实采样与许可','docs/research/sample-manifest-2026-10-22.md'),('character','角色生产方案','docs/research/character-production-plan.md'),('verification','实际验收与边界','docs/verification-2026-10-22.md'),('mobile','手机与全屏演奏','docs/mobile-performance-2026-10-22.md')]
nav=''.join(f'<a href="#{slug}">{title}</a>' for slug,title,_ in entries)
sections=[]
for slug,title,file in entries:
 text=(root/file).read_text()
 assert not any(x in text for x in ['/Users/','oauth_token','xsec_token='])
 if slug in {'product','audio','animation','recording','character'}:
  text='> 初轮研究快照：下文保留当时的建议、候选与待确认项。用户后续已确认真实音色和毛绒角色路线，并追加吉他/架子鼓；当前实现和验收以本页「计划与确认边界」「实际验收与边界」为准。\n\n'+text
 body=md.render(text).replace('<table>','<div class="table-wrap"><table>').replace('</table>','</table></div>')
 sections.append(f'<section id="{slug}" class="chapter"><span class="eyebrow">研究 · 2026-10-22</span><div class="prose">{body}</div></section>')
concept='character-concept-v1.png';shutil.copy2(root/'design'/concept,out/concept)
page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Miao Beat的作品、音色、动画、键位与轻量创作研究，保留来源、已确认路线和实际验收边界。"><title>Miao Beat · 轻量音乐创作研究</title><link rel="icon" href="/icons/miaoti.svg"><link rel="canonical" href="OWNER_ORIGIN/reviews/miao-beat/"><link rel="stylesheet" href="/reviews/style.css"><link rel="stylesheet" href="./review.css"></head><body><header class="topbar"><a class="brand" href="/reviews/">项目复盘与优化</a><a href="https://miao-beat.pages.dev/">去演奏 ↗</a></header><main class="reference"><header class="chapter-header"><span class="eyebrow">MIAO BEAT · 2026-10-22</span><h1>从“按键出声”，到自己的小小音乐。</h1><p>核心是跟着节拍器自由演奏。用户已确认先真实音色、再毛绒角色；吉他与架子鼓按追加要求实现。这里持续保留来源和实际验收边界。</p><div class="actions"><a href="https://miao-beat.pages.dev/">打开音乐工作台 ↗</a><a href="https://github.com/farmcan/miao-beat">独立仓库 ↗</a><a href="#plan">交付范围 ↓</a></div></header><aside class="decision"><h2>已经确认的推进顺序</h2><p><strong>先听审真实采样，再定角色生产路线。</strong>当前采用 smplr + 自托管真实钢琴、马林巴、尼龙弦吉他与八件架子鼓。角色已接入原创四组件2.5D毛绒猫，头部、左右爪和节拍反应分开；不依赖GIF切换，不是真3D。</p><p>当前新版采用四组自托管真实采样；旧事件文件保留原合成引擎。自动解码/音量检查和浏览器发声验证不等于主观听感或手机端延迟已验收。事件文件只保存时间与按键，导出/导入/回放不需要上传音频。</p></aside><figure class="concept"><img src="./character-concept-v1.png" width="1254" height="1254" alt="原创黑色毛绒小猫戴绿色耳机，前爪放在小键盘上，静态角色方向图"><figcaption><strong>原创角色方向图 v1</strong><br>内置 imagegen 生成，提示词与哈希保存在独立仓库 design/。这是静态概念图，尚不是3D模型或完成动画；试玩已使用由该方向衍生的四组件毛绒猫：头部轻跟随、左右爪可独立重打。这张旧图仍仅作美术方向对照。用户提供的追光猫笔记已核对制作描述，来源与未知项见动画章。</figcaption></figure><nav class="review-nav" aria-label="研究目录">'''+nav+'''</nav>'''+''.join(sections)+'''<footer class="footer"><a href="/reviews/">全部项目</a><span>研究快照 2026-10-22 · 事实、建议、待验证分开</span><a href="https://miao-beat.pages.dev/">去演奏 ↗</a></footer></main></body></html>'''
assert args.owner_origin.startswith('https://')
page=page.replace('OWNER_ORIGIN',html.escape(args.owner_origin.rstrip('/'),quote=True))
(out/'index.html').write_text(page)
(out/'review.css').write_text('''.reference{max-width:1120px}.actions{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}.actions a{border:1px solid #cbd1c8;border-radius:8px;padding:10px 14px;text-decoration:none}.decision{padding:22px;background:#f3f4eb;border:1px solid #cbd1c8;border-radius:12px;margin:25px 0;line-height:1.9}.decision h2{margin:0 0 12px}.concept{display:flex;align-items:center;gap:24px;background:#eeeee5;border-radius:12px;margin:25px 0;padding:20px}.concept img{width:240px;height:240px;object-fit:contain}.concept figcaption{font-size:14px;line-height:1.9;max-width:560px}.review-nav{display:flex;gap:8px;flex-wrap:wrap;padding:14px 0;border-block:1px solid #d5d7ce;background:#fafaf6;position:sticky;top:0;z-index:2}.review-nav a{padding:8px;font-size:13px}.chapter{padding-top:32px;scroll-margin-top:85px;border-bottom:1px solid #d8dace}.prose h1{font-size:28px;line-height:1.4}.prose h2{margin-top:32px}.table-wrap{overflow-x:auto;margin:22px 0}.prose table{font-size:13px;min-width:680px;line-height:1.8}.prose td,.prose th{padding:12px;vertical-align:top}.prose pre{overflow:auto;padding:16px;background:#f1f1eb}.prose a{overflow-wrap:anywhere}@media(max-width:600px){.concept{display:block}.concept img{display:block;margin:auto;width:220px;height:220px}.review-nav{position:static}.prose h1{font-size:23px}.decision{padding:16px}.actions{gap:8px}.actions a{font-size:12px}}''')
files={name:hashlib.sha256((out/name).read_bytes()).hexdigest() for name in ['index.html','review.css',concept]}
(out/'build-manifest.json').write_text(json.dumps({'source_repository':'https://github.com/farmcan/miao-beat','generated_date':'2026-10-22','files':files},indent=2)+'\n')
print('Exported 3 reviewed Miao Beat files; repository and recordings excluded')
